code.common:
float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

code.fragment:
float4 frag(UPEInput i)
{
    float2 p = i.uv * 2.0 - 1.0;
    float seed = frac(dot(i.color.rgb, float3(17.31, 31.7, 7.13)) * 3.7);
    float ang = atan2(p.y, p.x);
    // açı boyunca sürekli gürültü (dikissiz: sin/cos üzerinden)
    float2 q = float2(cos(ang), sin(ang)) * 1.3 + seed * 11.0;
    float wob = 1.0 + _Wobble * (vnoise(q) - 0.5) * 2.0;
    float r = length(p) / max(wob, 0.2);
    float core = exp(-r * r * _CoreSize);
    float halo = exp(-r * _HaloSize) * 0.4;
    float edge = 1.0 - smoothstep(0.75, 1.0, length(p));
    float tw = 1.0 - _Twinkle * 0.5 * (1.0 + sin(i.time * (16.0 + seed * 14.0) + seed * 30.0));
    float3 col = (_Core.rgb * core + _Halo.rgb * halo) * edge * tw * i.color.rgb * i.color.a;
    return float4(col, 1.0);
}
